<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import UiIcon from './UiIcon.svelte';
  type Recording={active:boolean;started_at:number;duration_seconds:number;pid:number;message:string;error:boolean};
  type Workspace={supported:boolean;ffmpeg_available:boolean;ffprobe_available:boolean;game_available:boolean;recording:Recording;clips:{id:string;size_bytes:number;modified_ms:number}[];note:string};
  let workspace=$state<Workspace|null>(null), busy=$state(''), error=$state(''), seconds=$state(30), fps=$state(30), quality=$state('720p'), consent=$state(false), now=$state(Date.now());
  let elapsed=$derived(workspace?.recording.active?Math.max(0,Math.floor((now-workspace.recording.started_at)/1000)):0);
  let loading=false, alive=true;
  async function load(){if(loading)return;loading=true;try{const value=await invoke<Workspace>('tp_clips_workspace');if(alive){workspace=value;error='';}}catch(e){if(alive)error=String(e);}finally{loading=false;}}
  async function perform(key:string,action:()=>Promise<unknown>){if(busy)return;busy=key;error='';try{await action();await load();}catch(e){error=String(e);}finally{busy='';}}
  async function start(){await perform('start',async()=>{await invoke<Recording>('tp_clips_start',{seconds,fps,quality,consent});consent=false;});}
  onMount(()=>{alive=true;void load();const timer=setInterval(()=>{now=Date.now();if(!document.hidden)void load();},2000);return()=>{alive=false;clearInterval(timer);};});
</script>

<section class="clips"><header><div><span>TP LABS · CAPTURA LOCAL OPCIONAL</span><h2><UiIcon name="camera" size={25}/>TP Clips</h2><p>Graba una escena de Minecraft y guárdala como MP4 en tu equipo.</p></div><button disabled={!!busy} onclick={() => void perform('folder',()=>invoke('tp_clips_folder'))}><UiIcon name="folder" size={16}/>Abrir carpeta</button></header>
  {#if error}<p role="alert" class="error">{error}</p>{/if}
  {#if workspace}
    <p class="notice">{workspace.note}</p>
    {#if !workspace.supported}<p class="error">La captura de ventana de esta versión está disponible solo en Windows.</p>{:else if !workspace.ffmpeg_available||!workspace.ffprobe_available}<p class="error">Falta {(!workspace.ffmpeg_available?'FFmpeg':'')+(!workspace.ffmpeg_available&&!workspace.ffprobe_available?' y ':'')+(!workspace.ffprobe_available?'ffprobe':'')} en PATH. Instala una distribución confiable compatible con gdigrab y libx264 y reinicia el launcher. TP no descarga ni instala ejecutables automáticamente.</p>{/if}
    <div class="recorder"><div class="fields"><label>Grabar los próximos<select disabled={workspace.recording.active||!!busy} bind:value={seconds}><option value={15}>15 segundos</option><option value={30}>30 segundos</option><option value={60}>60 segundos</option><option value={120}>120 segundos</option></select></label><label>Resolución máxima<select disabled={workspace.recording.active||!!busy} bind:value={quality}><option value="720p">720p · menor coste</option><option value="1080p">1080p</option></select></label><label>Fotogramas por segundo<select disabled={workspace.recording.active||!!busy} bind:value={fps}><option value={30}>30 FPS</option><option value={60}>60 FPS · mayor coste</option></select></label></div>
      <div class="privacy"><UiIcon name="shield"/><div><strong>Sin micrófono, sin audio y sin publicación</strong><p>Se captura únicamente la ventana del juego iniciada por TP. No se graban los segundos anteriores. El archivo se verifica antes de aparecer en tu biblioteca.</p></div></div>
      {#if workspace.recording.active}<div role="status" class="recording"><i></i><strong>Grabación en curso · {elapsed} / {workspace.recording.duration_seconds} s</strong><button disabled={!!busy} onclick={() => void perform('stop',()=>invoke('tp_clips_stop'))}>Detener y guardar</button></div><progress value={Math.min(elapsed,workspace.recording.duration_seconds)} max={workspace.recording.duration_seconds} aria-label="Progreso de la grabación"></progress>{:else}
        <label class="consent"><input type="checkbox" bind:checked={consent}/>Quiero grabar la ventana de Minecraft ahora. Entiendo que puede afectar a los FPS.</label>
        <button class="start" disabled={!!busy||!consent||!workspace.supported||!workspace.ffmpeg_available||!workspace.ffprobe_available||!workspace.game_available} onclick={() => void start()}><UiIcon name="camera" size={18}/>Comenzar grabación</button>
        {#if !workspace.game_available}<small>Abre Minecraft desde TP Launcher para habilitar la captura de su ventana.</small>{/if}
      {/if}
      {#if workspace.recording.message}<p role="status" class:error={workspace.recording.error}>{workspace.recording.message}</p>{/if}
    </div>
    <div class="library"><div class="heading"><h3>Clips guardados</h3><button disabled={!!busy} onclick={() => void load()}><UiIcon name="refresh" size={14}/>Actualizar</button></div>{#each workspace.clips as clip}<article><UiIcon name="image" size={24}/><div><strong>{new Date(clip.modified_ms).toLocaleString()}</strong><small>{(clip.size_bytes/1024/1024).toFixed(1)} MB · MP4</small></div><button disabled={!!busy} onclick={() => void perform(clip.id,()=>invoke('tp_clips_open',{id:clip.id}))}><UiIcon name="play" size={15}/>Abrir vídeo</button></article>{:else}<p>No hay clips grabados todavía. Las capturas F2 siguen disponibles en Capturas.</p>{/each}</div>
  {:else}<p role="status">Comprobando captura local…</p>{/if}
</section>

<style>
  .clips{display:grid;gap:22px;color:#f2eaf8}header,.heading{display:flex;align-items:center;justify-content:space-between;gap:18px}header span{font-size:10px;letter-spacing:.12em;color:#c199eb}h2{display:flex;align-items:center;gap:10px;font-size:26px;margin:8px 0}h3{margin:0}p{font-size:13px;line-height:1.6;color:#b7acc5;margin:6px 0}button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 15px;background:#251a33;border:1px solid #685076;border-radius:7px;color:#f3eafa;font:inherit;cursor:pointer}button:hover:not(:disabled){background:#40274f}button:disabled{opacity:.45;cursor:not-allowed}.notice,.recorder,.library{padding:22px;background:#110d19ed;border:1px solid #3d3049;border-radius:10px}.notice{border-left:3px solid #ad6ce0;margin:0}.recorder{display:grid;gap:18px}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}label{display:grid;gap:9px;font-size:13px;font-weight:600}select{padding:11px;border:1px solid #574263;border-radius:6px;background:#1d1528;color:#f3eafa;font:inherit;color-scheme:dark}.privacy{display:flex;gap:13px;padding:15px;background:#1b1524;border-radius:8px}.privacy :global(svg){flex:none;color:#c390e8}.privacy strong{font-size:13px}.privacy p{margin-bottom:0}.consent{display:flex;align-items:flex-start;line-height:1.5}.consent input{accent-color:#b169e4;flex:none}.start{justify-self:start;background:#823db3;border-color:#c287eb;font-weight:700}small{font-size:12px;color:#a99bb7}.recording{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.recording i{width:10px;height:10px;border-radius:50%;background:#f66b95;box-shadow:0 0 0 4px #f66b9526}.recording button{margin-left:auto}progress{width:100%;height:8px;accent-color:#b573e8}.error{padding:12px;background:#371b25;border:1px solid #8a4558;border-radius:6px;color:#ffbfcc}.library{display:grid;gap:13px}.library article{display:flex;align-items:center;gap:15px;padding:15px;background:#21172c;border-radius:7px}.library article>div{display:grid;gap:7px;flex:1}.library article strong{font-size:13px}.library article :global(svg){color:#c19add}@media(max-width:800px){header{align-items:flex-start;flex-direction:column}.fields{grid-template-columns:1fr}.library article{flex-wrap:wrap}}
</style>
